return $input.all()
  .map((i) => i.json)
  .filter((r) => r.type === 'keyword-report')
  .map((r) => ({ json: {
    week: new Date().toISOString().slice(0, 10),
    keyword: r.searchTerm,
    averageInterest: r.averageInterest,
    latestInterest: r.latestInterest,
    changePercent: r.changePercent,
    trend: r.trendDirection,
    topRisingQuery: (r.risingQueries || [])[0]?.query || '',
    summary: r.summary,
  } }));
